const theme = context.grafana.theme;
const text = theme.colors.text.primary;
const muted = theme.colors.text.secondary;
const lines = theme.colors.border.weak;
const frame = context.panel.data.series[0];
const col = (name) => {
  const field = frame && frame.fields.find((f) => f.name === name);
  return field ? Array.from(field.values) : [];
};
// Distinct aircraft by country of registration.
// A click on a bar filters the whole dashboard by it ($$country); a click on the
// picked bar clears the filter.
const VAR = 'country';
const COLORS = {};
const values = col('value').reverse();
const labels = col('label').reverse();
const counts = col('aircraft').reverse();
const picked = context.grafana.replaceVariables('${' + VAR + '}');
const location = context.grafana.locationService;

const chart = context.panel.chart;
chart.off('click');
chart.on('click', (event) => {
  const value = values[event.dataIndex];
  const current = context.grafana.replaceVariables('${' + VAR + '}');
  location.partial({ ['var-' + VAR]: value === current ? '' : value }, true);
});

return {
  animation: false,
  grid: { left: 8, right: 56, top: 8, bottom: 8, containLabel: true },
  tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' },
             formatter: (items) => `<b>${labels[items[0].dataIndex]}</b><br/>${counts[items[0].dataIndex].toLocaleString()} aircraft<br/><i>click to ${values[items[0].dataIndex] === picked ? 'clear the filter' : 'filter by it'}</i>` },
  xAxis: { type: 'value', axisLabel: { show: false }, splitLine: { show: false } },
  yAxis: { type: 'category', data: labels, axisLabel: { color: text, width: 150, overflow: 'truncate' },
           axisLine: { lineStyle: { color: lines } } },
  series: [{
    name: 'Aircraft', type: 'bar', barMaxWidth: 16, cursor: 'pointer',
    data: counts.map((v, i) => ({
      value: v,
      itemStyle: { color: COLORS[values[i]] || '#00A6CA', opacity: !picked || values[i] === picked ? 1 : 0.3 },
    })),
    label: { show: true, position: 'right', color: muted, formatter: (p) => p.value.toLocaleString() },
  }],
};

const theme = context.grafana.theme;
const text = theme.colors.text.primary;
const muted = theme.colors.text.secondary;
const lines = theme.colors.border.weak;
const frame = context.panel.data.series[0];
const col = (name) => {
  const field = frame && frame.fields.find((f) => f.name === name);
  return field ? Array.from(field.values) : [];
};
// Distinct aircraft heard per interval, stacked by kind of flight. An interval
// with no bar is a gap in the recording, not empty skies.
const COLORS = {"Airline": "#00A6CA", "Cargo": "#F29E2E", "Private & general aviation": "#90EB9D", "Helicopter": "#C77DFF", "Military": "#E5484D", "Ground & other": "#8B8D98"};
const times = col('time');
const kinds = col('kind');
const heard = col('heard');
const order = Object.keys(COLORS).filter((k) => kinds.includes(k));
const buckets = [...new Set(times)].sort((a, b) => a - b);
const series = order.map((k) => {
  const at = new Map();
  kinds.forEach((kind, i) => kind === k && at.set(times[i], heard[i]));
  return { name: k, type: 'bar', stack: 'all', barMaxWidth: 14, itemStyle: { color: COLORS[k] },
           data: buckets.map((t) => [t, at.get(t) ?? 0]) };
});
return {
  animation: false,
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 10, itemHeight: 10 },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  tooltip: { trigger: 'axis' },
  xAxis: { type: 'time', axisLabel: { color: muted }, axisLine: { lineStyle: { color: lines } } },
  yAxis: { type: 'value', min: 0, axisLabel: { color: muted }, splitLine: { lineStyle: { color: lines } } },
  series,
};

