    text: picked ? 'Nothing recorded for ' + picked + ' in this range' : 'Pick an aircraft on the map',
    left: 'center', top: 'middle', textStyle: { color: muted, fontSize: 14, fontWeight: 'normal' },
  },
  legend: { top: 0, textStyle: { color: muted } },
