    { type: 'value', name: 'ft', nameTextStyle: { color: muted }, axisLabel: { color: muted }, splitLine: { lineStyle: { color: lines } } },
    { type: 'value', name: 'kt', nameTextStyle: { color: muted }, axisLabel: { color: muted }, splitLine: { show: false } },
  ],
  series: [
    { name: 'Altitude (ft)', type: 'line', showSymbol: false, itemStyle: { color: '#00A6CA' }, data: times.map((t, i) => [t, alt[i]]) },
    { name: 'Ground speed (kt)', type: 'line', showSymbol: false, yAxisIndex: 1, itemStyle: { color: '#F29E2E' }, data: times.map((t, i) => [t, gs[i]]) },
  ],
};

